    /**
     * Tests creating a new Subscription.
     *
     * @return    Subscription
     */
    public Subscription testCreate() throws Throwable {
    Subscription entity = null;

    LOGGER.info( "SubscriptionTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Subscription");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Subscription" );

    try {
        entity = service.createSubscription( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getSubscriptionId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Subscription with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Subscription.
     *
     * @return    Subscription
     */
    public Subscription testRead() throws Throwable {
    LOGGER.info( "SubscriptionTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Subscription" );

    Subscription entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Subscription with primary key" );
    msg.append( theId );

    try {
        entity = service.getSubscription( new SubscriptionFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getSubscriptionId();

        LOGGER.info( "-- Successfully found Subscription " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Subscription.
     *
     * @return    Subscription
     */
    public Subscription testUpdate() throws Throwable {
    LOGGER.info( "SubscriptionTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Subscription." );

    StringBuilder msg = new StringBuilder( "Failed to update a Subscription : " );
    Subscription entity = null;

    try {
        UpdateSubscriptionCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setSubscriptionId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Subscription." );

        entity = service.updateSubscription( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Subscription - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Subscription.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "SubscriptionTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Subscription." );

    try {
        DeleteSubscriptionCommand deleteCommand = new DeleteSubscriptionCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Subscription with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Subscription with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Subscriptions.
     *
     * @return    Collection
     */
    public List<Subscription> testGetAll() throws Throwable {
    LOGGER.info( "SubscriptionTest:testGetAll() - Retrieving Collection of Subscriptions:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Subscription : " );
    List<Subscription> collection  = null;

    try {
        // call the static get method on the SubscriptionService
        collection = service.getAllSubscription();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Subscription currEntity  = null;
            Iterator<Subscription> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSubscriptionId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

